    private static final Map<String, VatExemptionReason> BY_CODE = byCode();

    private final String code;

    private final String publishedName;

    private final String listId;

    VatExemptionReason(String code, String publishedName, String listId) {
        this.code = code;
        this.publishedName = publishedName;
        this.listId = listId;
    }

    /**
     * Returns the constant carrying a code.
     *
     * <p>The comparison is exact, code point by code point: a code list is a list of
     * codes and not of their spellings.
     *
     * @param code the code
     * @return the constant
     * @throws IllegalArgumentException if the snapshot does not carry the code
     * @throws NullPointerException     if {@code code} is {@code null}
     */
    public static VatExemptionReason of(String code) {
        VatExemptionReason value = BY_CODE.get(Objects.requireNonNull(code, "code"));
        if (value == null) {
            throw new IllegalArgumentException("the snapshot of VatExemptionReason does not carry the code "
                    + code + "; VatExemptionReason.custom(code) represents a code it does not have");
        }
        return value;
    }

    /**
     * Returns the constant carrying a code, or a custom code where there is none.
     *
     * @param code the code as a document carries it
     * @return the constant or a {@link CustomCode}
     * @throws NullPointerException     if {@code code} is {@code null}
     * @throws IllegalArgumentException if the code is blank
     */
    public static Coded resolve(String code) {
        VatExemptionReason value = BY_CODE.get(Objects.requireNonNull(code, "code"));
        return value != null ? value : new CustomCode("VatExemptionReason", code);
    }

    /**
     * Returns a code the snapshot does not carry.
     *
     * @param code the code
     * @return the custom code
     * @throws IllegalArgumentException if the snapshot carries the code, which has a
     *                                  constant and must not have a second representation,
     *                                  or if the code is blank
     * @throws NullPointerException     if {@code code} is {@code null}
     */
    public static Coded custom(String code) {
        VatExemptionReason value = BY_CODE.get(Objects.requireNonNull(code, "code"));
        if (value != null) {
            throw new IllegalArgumentException("the snapshot of VatExemptionReason carries the code "
                    + code + " as " + value.name());
        }
        return new CustomCode("VatExemptionReason", code);
    }

    /**
     * Returns the code as it is written into the document.
     *
     * @return the code
     */
    @Override
    public String code() {
        return code;
    }

    /**
     * Returns the name the publisher of the list gives the code.
     *
     * @return the name, empty where the publisher gives none
     */
    @Override
    public String publishedName() {
        return publishedName;
    }

    /**
     * Returns the identifier of the code list the constant came from.
     *
     * @return the list identifier, for example {@code vatex}
     */
    @Override
    public String listId() {
        return listId;
    }

    private static Map<String, VatExemptionReason> byCode() {
        Map<String, VatExemptionReason> byCode = new LinkedHashMap<>();
        for (VatExemptionReason value : values()) {
            byCode.put(value.code, value);
        }
        return Map.copyOf(byCode);
    }
